const WEEKS=[["Clarity first", "الوضوح أولاً", "Get to your main message before the background.", "ابدأ بالرسالة الأساسية قبل التفاصيل."], ["Words and structure", "الكلمات وتنظيم الأفكار", "Retrieve, replace, and organize without rushing.", "استرجع الكلمات أو استبدلها ونظّم أفكارك دون استعجال."], ["Make people want to listen", "اجعل رسالتك تستحق الانتباه", "Lead with relevance, impact, and a concise example.", "ابدأ بالأهمية والأثر ومثال مختصر."], ["Calm assertiveness", "الحزم الهادئ", "Protect your turn and manage frustration without raising your voice.", "حافظ على دورك وتعامل مع الانزعاج دون رفع الصوت."]];
const WORKED_EXAMPLES=[{"en":{"word":"Preparedness means getting ready before something happens, so essential supplies can move quickly.","point":"I recommend planning emergency deliveries before a crisis.","reason":"Advance planning reduces delays.","close":"Let us confirm the delivery routes this week.","extra":"For example, we can pre-agree customs procedures with local authorities."},"ar":{"word":"الجاهزية تعني الاستعداد قبل وقوع الحدث حتى تصل الإمدادات بسرعة.","point":"أوصي بالتخطيط لتوصيل الإمدادات قبل حدوث الأزمة.","reason":"التخطيط المسبق يقلل التأخير.","close":"لنؤكد مسارات التوصيل هذا الأسبوع.","extra":"مثلاً، يمكننا الاتفاق مسبقاً على الإجراءات الجمركية مع الجهات المعنية."}},{"en":{"word":"Priority is what deserves attention before less important tasks.","point":"I suggest we spend Saturday outdoors with the children.","reason":"It gives us time together away from screens.","close":"Let us choose a park tonight.","extra":"For example, we could pack lunch and spend two hours playing."},"ar":{"word":"الأولوية هي الأمر الذي يستحق الاهتمام قبل غيره.","point":"أقترح أن نقضي يوم السبت خارج المنزل مع الأطفال.","reason":"هذا يمنحنا وقتاً معاً بعيداً عن الشاشات.","close":"لنختر حديقة هذا المساء.","extra":"مثلاً، يمكننا تجهيز الغداء وقضاء ساعتين في اللعب."}},{"en":{"word":"An approval is formal permission to proceed.","point":"I recommend simplifying the approval process.","reason":"Too many steps slow decisions.","close":"Let us test a shorter process for one month.","extra":"For example, a single agreed checkpoint could replace three email exchanges."},"ar":{"word":"الموافقة هي الإذن الرسمي بالمضي في إجراء معين.","point":"أوصي بتبسيط إجراءات الموافقة.","reason":"كثرة الخطوات تؤخر اتخاذ القرار.","close":"لنجرب إجراءً أقصر لمدة شهر.","extra":"مثلاً، يمكن اعتماد نقطة مراجعة واحدة بدلاً من ثلاث مراسلات."}},{"en":{"word":"Logistics is organizing how things are stored and delivered to the right place.","point":"I think this process can be explained simply.","reason":"People understand it faster when we describe what it achieves.","close":"I will use one everyday example.","extra":"For example, it is like planning how groceries reach your home on time."},"ar":{"word":"الخدمات اللوجستية تعني تنظيم تخزين الأشياء ونقلها إلى المكان الصحيح.","point":"أعتقد أنه يمكن شرح هذا الإجراء بطريقة بسيطة.","reason":"يفهمه الناس أسرع عندما نشرح الهدف منه.","close":"سأستخدم مثالاً واحداً من الحياة اليومية.","extra":"مثلاً، يشبه التخطيط لوصول مشتريات المنزل في الوقت المناسب."}},{"en":{"word":"A decision is the choice we make after considering our options.","point":"I decided to change the schedule.","reason":"The previous timing was not practical for everyone.","close":"We will review the new timing next week.","extra":"For example, changing pickup by half an hour avoids rushing."},"ar":{"word":"القرار هو الخيار الذي نتخذه بعد دراسة البدائل.","point":"قررت تغيير الجدول.","reason":"التوقيت السابق لم يكن مناسباً للجميع.","close":"سنراجع التوقيت الجديد الأسبوع المقبل.","extra":"مثلاً، تغيير وقت الاستلام نصف ساعة يخفف الاستعجال."}},{"en":{"word":"Efficiency means getting a useful result with less wasted time or effort.","point":"We should introduce a single tracking sheet.","reason":"It will reduce duplicate updates.","close":"I suggest we pilot it with one team.","extra":"For example, everyone could update the same status instead of sending separate emails."},"ar":{"word":"الكفاءة تعني تحقيق نتيجة جيدة بوقت وجهد أقل.","point":"أقترح اعتماد جدول متابعة واحد.","reason":"سيقلل ذلك من تكرار التحديثات.","close":"لنجربه مع فريق واحد أولاً.","extra":"مثلاً، يستطيع الجميع تحديث حالة العمل في مكان واحد بدلاً من إرسال رسائل منفصلة."}},{"en":{"word":"Clarity means making something easy to understand.","point":"My recommendation is to agree on one clear priority.","reason":"It will keep everyone focused.","close":"Let us confirm who will do what today.","extra":"For example, we can name the single action that matters most this week."},"ar":{"word":"الوضوح هو التعبير عن الفكرة بطريقة يسهل فهمها.","point":"أوصي بالاتفاق على أولوية واحدة واضحة.","reason":"هذا يساعد الجميع على التركيز.","close":"لنحدد اليوم المسؤول عن كل خطوة.","extra":"مثلاً، يمكن تسمية أهم عمل يجب إنجازه هذا الأسبوع."}},{"en":{"word":"Negotiation is a discussion aimed at finding an agreement.","point":"Customs clearance allows imported goods to enter legally.","reason":"It checks documents, duties and permissions.","close":"A simple description is enough to explain the process.","extra":"For example, emergency medicines may need an import permit and release at the border."},"ar":{"word":"التفاوض هو نقاش بهدف الوصول إلى اتفاق.","point":"يسمح التخليص الجمركي بدخول البضائع إلى البلد بصورة قانونية.","reason":"وتشمل العملية التحقق من المستندات والتصاريح.","close":"يكفي شرح مبسط لتوضيح العملية.","extra":"مثلاً، قد تحتاج الأدوية الطارئة إلى تصريح استيراد وإفراج عند الحدود."}},{"en":{"word":"Coordination means making different people or tasks work together.","point":"Urgent tasks require immediate attention, but important tasks protect longer-term goals.","reason":"Confusing the two can distort priorities.","close":"Let us plan both separately.","extra":"For example, a shipment stuck at customs may be urgent, while improving the procedure is important."},"ar":{"word":"التنسيق هو جعل عدة أشخاص أو مهام يعملون معاً.","point":"المهام العاجلة تحتاج تدخلاً فورياً، أما المهمة فتحمي أهدافنا المستقبلية.","reason":"الخلط بينهما يؤثر على ترتيب الأولويات.","close":"لنخطط لكل منهما بشكل منفصل.","extra":"مثلاً، شحنة عالقة في الجمارك مسألة عاجلة، أما تحسين الإجراء فمسألة مهمة."}},{"en":{"word":"A bottleneck is one step that slows the whole process.","point":"The project has three issues, but I would group them into two areas.","reason":"Approvals affect decisions, while transport and storage affect delivery.","close":"Let us assign one owner to each area.","extra":"For example, fixing an approval bottleneck will not by itself create warehouse space."},"ar":{"word":"عنق الزجاجة هو خطوة تبطئ العملية بكاملها.","point":"لدى المشروع ثلاث مشكلات، لكن يمكن جمعها ضمن مجالين.","reason":"الموافقات تؤثر على القرار، والنقل والتخزين يؤثران على التسليم.","close":"لنحدد مسؤولاً عن كل مجال.","extra":"مثلاً، حل مشكلة الموافقة لا يوفر تلقائياً مساحة مستودع."}},{"en":{"word":"A trade-off means gaining one advantage while accepting a cost or limitation.","point":"I prefer the less expensive option for our family.","reason":"It covers what we actually need.","close":"Let us compare the two choices once more.","extra":"For example, we can save money without losing an important safety feature."},"ar":{"word":"الموازنة بين الخيارات تعني قبول جانب سلبي مقابل ميزة مهمة.","point":"أفضل الخيار الأقل تكلفة لعائلتنا.","reason":"لأنه يلبي احتياجاتنا الحقيقية.","close":"لنقارن الخيارين مرة أخيرة.","extra":"مثلاً، نستطيع التوفير دون التنازل عن خاصية أساسية للسلامة."}},{"en":{"word":"A sequence is the order in which steps happen.","point":"The meeting identified one main delay.","reason":"Responsibilities were unclear.","close":"We agreed to assign owners and check progress Friday.","extra":"For example, we will confirm the accountable person before discussing new deadlines."},"ar":{"word":"التسلسل هو ترتيب الخطوات التي تحدث بها الأمور.","point":"حدد الاجتماع سبباً رئيسياً للتأخير.","reason":"لم تكن المسؤوليات واضحة.","close":"اتفقنا على تحديد المسؤولين ومراجعة التقدم يوم الجمعة.","extra":"مثلاً، سنحدد الشخص المسؤول قبل مناقشة المواعيد الجديدة."}},{"en":{"word":"Risk is the possibility that something could go wrong.","point":"The delivery risk is concentrated at the border.","reason":"The permit may take longer than planned.","close":"We should confirm requirements before dispatch.","extra":"For example, a missing certificate can delay an otherwise ready shipment."},"ar":{"word":"الخطر هو احتمال حدوث أمر غير مرغوب فيه.","point":"تتركز مخاطر التسليم عند الحدود.","reason":"قد يستغرق التصريح وقتاً أطول من المتوقع.","close":"علينا التأكد من المتطلبات قبل الإرسال.","extra":"مثلاً، شهادة ناقصة يمكن أن تؤخر شحنة جاهزة."}},{"en":{"word":"Resilience is the ability to recover and keep working after difficulty.","point":"A good preparedness system keeps operations moving when conditions change.","reason":"It provides alternatives before a disruption occurs.","close":"We should document our backup options.","extra":"For example, one alternative route can prevent a complete delivery stop."},"ar":{"word":"المرونة التشغيلية هي القدرة على الاستمرار والتعافي بعد التعطل.","point":"يحافظ نظام الجاهزية الجيد على سير العمل عند تغير الظروف.","reason":"لأنه يوفر بدائل قبل حدوث التعطل.","close":"علينا توثيق خياراتنا البديلة.","extra":"مثلاً، قد يمنع مسار بديل توقف التوصيل بالكامل."}},{"en":{"word":"Impact is the effect that an action or problem creates.","point":"This issue could delay supplies reaching families.","reason":"The current process adds avoidable waiting time.","close":"I recommend resolving the main approval step today.","extra":"For example, every delayed signature can hold up an entire shipment."},"ar":{"word":"الأثر هو النتيجة التي يسببها قرار أو مشكلة.","point":"قد تؤخر هذه المشكلة وصول الإمدادات إلى الأسر.","reason":"فالإجراء الحالي يضيف وقت انتظار غير ضروري.","close":"أوصي بحل خطوة الموافقة الأساسية اليوم.","extra":"مثلاً، تأخر توقيع واحد قد يوقف شحنة بأكملها."}},{"en":{"word":"An alternative is another possible way to achieve the same goal.","point":"We can keep the current process or move to a simpler one.","reason":"The simpler option will take fewer steps.","close":"I recommend a short trial before deciding permanently.","extra":"For example, one review meeting may replace a chain of emails."},"ar":{"word":"البديل هو طريقة أخرى لتحقيق الهدف نفسه.","point":"يمكننا الاستمرار بالإجراء الحالي أو اعتماد طريقة أبسط.","reason":"الطريقة الأبسط تحتاج خطوات أقل.","close":"أوصي بتجربة قصيرة قبل القرار النهائي.","extra":"مثلاً، قد يغني اجتماع مراجعة واحد عن سلسلة رسائل."}},{"en":{"word":"A benefit is a positive result someone receives.","point":"I suggest we adjust the family budget this month.","reason":"It will protect our savings without cutting essential needs.","close":"Let us review flexible spending together.","extra":"For example, fewer delivery orders can create room for a family outing."},"ar":{"word":"الفائدة هي النتيجة الإيجابية التي يحصل عليها الشخص.","point":"أقترح تعديل ميزانية العائلة هذا الشهر.","reason":"لنحافظ على الادخار دون المساس بالاحتياجات الأساسية.","close":"لنراجع المصروفات المرنة معاً.","extra":"مثلاً، تقليل طلبات التوصيل قد يتيح ميزانية لنزهة عائلية."}},{"en":{"word":"An example is one specific case that makes an idea easier to understand.","point":"We should improve how we confirm deliveries.","reason":"Unclear confirmation causes repeated follow-up.","close":"Let us use one standard receipt format.","extra":"For example, a signed receipt with date and quantity avoids three separate calls."},"ar":{"word":"المثال حالة محددة تساعد على توضيح فكرة عامة.","point":"علينا تحسين طريقة تأكيد استلام الشحنات.","reason":"التأكيد غير الواضح يسبب المتابعة المتكررة.","close":"لنستخدم نموذج استلام موحداً.","extra":"مثلاً، إيصال موقع مع التاريخ والكمية يوفر ثلاث مكالمات متابعة."}},{"en":{"word":"Engagement means active participation in a conversation or activity.","point":"I suggest a shorter weekly team check-in.","reason":"It will allow faster decisions.","close":"What concern would you want us to address before testing it?","extra":"For example, each person could share one risk and one required decision."},"ar":{"word":"التفاعل يعني المشاركة الفعلية في الحوار أو النشاط.","point":"أقترح اجتماع متابعة أسبوعياً أقصر.","reason":"سيساعد ذلك على اتخاذ قرارات أسرع.","close":"ما القلق الذي ينبغي معالجته قبل التجربة؟","extra":"مثلاً، يشارك كل شخص خطراً واحداً وقراراً مطلوباً."}},{"en":{"word":"Confidence is being able to speak calmly even without perfect words.","point":"I support the revised plan.","reason":"It addresses the main problem at an acceptable cost.","close":"I recommend moving forward after the final check.","extra":"For example, the revised delivery dates are realistic for the available transport."},"ar":{"word":"الثقة في الحديث تعني الكلام بهدوء حتى لو لم نجد الكلمات المثالية.","point":"أنا أؤيد الخطة المعدلة.","reason":"لأنها تعالج المشكلة الأساسية بتكلفة مقبولة.","close":"أوصي بالمضي بها بعد المراجعة الأخيرة.","extra":"مثلاً، مواعيد التسليم الجديدة واقعية بالنسبة للنقل المتاح."}},{"en":{"word":"A recommendation is a clear suggestion supported by a reason.","point":"I recommend making the process simpler.","reason":"It will reduce repeated work for everyone.","close":"Can we agree to test it next week?","extra":"For example, a short shared checklist could prevent repeated clarifications."},"ar":{"word":"التوصية هي اقتراح واضح يقوم على سبب محدد.","point":"أوصي بتبسيط الإجراء.","reason":"هذا سيقلل الأعمال المكررة للجميع.","close":"هل نتفق على تجربته الأسبوع المقبل؟","extra":"مثلاً، قائمة تحقق مشتركة قصيرة تمنع تكرار طلب التوضيح."}},{"en":{"word":"A boundary is a calm statement of how you need to be treated.","point":"I want to finish one important point before we move on.","reason":"It explains the decision I am recommending.","close":"I will then welcome your questions.","extra":"For example, I can summarize the issue in two sentences before opening discussion."},"ar":{"word":"الحدود في الحوار هي التعبير بهدوء عن الطريقة التي تريد أن تعامل بها.","point":"أريد أن أكمل نقطة مهمة قبل أن ننتقل إلى موضوع آخر.","reason":"فهي تشرح القرار الذي أوصي به.","close":"بعدها يسعدني سماع أسئلتكم.","extra":"مثلاً، يمكنني تلخيص المشكلة بجملتين قبل فتح النقاش."}},{"en":{"word":"An assumption is something we believe without checking enough evidence.","point":"I was interrupted, and I felt dismissed.","reason":"But I cannot know the other person’s intention from that alone.","close":"I will ask for space to finish calmly.","extra":"For example, the other person may have been excited rather than disrespectful."},"ar":{"word":"الافتراض هو الاعتقاد بشيء من دون التأكد منه بأدلة كافية.","point":"قاطعني أحدهم وشعرت أنه تجاهلني.","reason":"لكنني لا أعرف نيته من المقاطعة وحدها.","close":"سأطلب بهدوء فرصة لإكمال كلامي.","extra":"مثلاً، ربما قاطعني بحماس وليس بقصد قلة الاحترام."}},{"en":{"word":"Disagreement means having a different view without attacking the person.","point":"I understand your concern, but I still recommend this approach.","reason":"The evidence suggests it will reduce delays.","close":"Let us test it against the main risks.","extra":"For example, we can run a two-week pilot rather than argue about every possibility."},"ar":{"word":"الاختلاف هو تبني وجهة نظر أخرى من دون مهاجمة الشخص.","point":"أتفهم قلقك لكنني ما زلت أوصي بهذا النهج.","reason":"المعطيات تشير إلى أنه سيقلل التأخير.","close":"لنجربه مقابل المخاطر الأساسية.","extra":"مثلاً، نستطيع إجراء تجربة لأسبوعين بدلاً من مناقشة كل احتمال."}},{"en":{"word":"Respect is treating a person and their views with consideration.","point":"I would like to finish speaking before we decide.","reason":"It helps me explain my concern clearly.","close":"Then I want to hear your view.","extra":"For example, we can each take a minute without interrupting."},"ar":{"word":"الاحترام هو التعامل مع الشخص وآرائه بتقدير.","point":"أود إكمال حديثي قبل اتخاذ القرار.","reason":"حتى أتمكن من توضيح ما يقلقني.","close":"ثم أريد أن أسمع وجهة نظرك.","extra":"مثلاً، يمكن لكل منا أن يتحدث دقيقة من دون مقاطعة."}},{"en":{"word":"A decision is the option chosen after considering available information.","point":"My update has one main message: the plan needs one decision today.","reason":"Without it, the team cannot confirm delivery.","close":"I recommend approving the proposed route.","extra":"For example, the transporter needs an answer before tomorrow’s dispatch."},"ar":{"word":"القرار هو الخيار الذي نتخذه بعد تقييم المعلومات المتاحة.","point":"رسالتي الأساسية هي أن الخطة تحتاج قراراً واحداً اليوم.","reason":"من دونه لن يستطيع الفريق تأكيد التسليم.","close":"أوصي بالموافقة على المسار المقترح.","extra":"مثلاً، يحتاج الناقل إلى جواب قبل إرسال الشحنة غداً."}},{"en":{"word":"Evidence is information that supports a conclusion.","point":"I chose this approach because it reduced the main risk.","reason":"The earlier option caused repeated delays.","close":"I can share the evidence if that would help.","extra":"For example, the last three deliveries took longer under the previous procedure."},"ar":{"word":"الدليل هو معلومة تدعم استنتاجاً معيناً.","point":"اخترت هذا النهج لأنه يقلل الخطر الأساسي.","reason":"فالخيار السابق تسبب بتأخير متكرر.","close":"يمكنني مشاركة الأدلة عند الحاجة.","extra":"مثلاً، استغرقت آخر ثلاث شحنات وقتاً أطول بالإجراء القديم."}},{"en":{"word":"Articulation is putting your ideas into words that listeners can understand.","point":"My recommendation is to start with the simplest workable solution.","reason":"It is easier to implement and evaluate.","close":"Let us agree on the first step today.","extra":"For example, we can test it with one team before expanding."},"ar":{"word":"حسن التعبير هو تحويل أفكارك إلى كلمات يفهمها المستمع.","point":"أوصي بالبدء بأبسط حل قابل للتنفيذ.","reason":"فهو أسهل في التطبيق والتقييم.","close":"لنتفق على الخطوة الأولى اليوم.","extra":"مثلاً، يمكن تجربته مع فريق واحد قبل التوسع."}}];
