let lang='en',day=1,step=0,activeTab='today',data={version:1,days:{}};
let currentAudio=null,recorder=null,recordChunks=[],sec=300,timeLeft=300,running=false,timeHandle=null;
const el=id=>document.getElementById(id);const t=k=>I[lang][k];const phraseKey=k=>lang==='ar'?k+'Ar':k;
function textFor(obj,k){return obj[phraseKey(k)]??obj[k]??''};function setText(id,s){el(id).textContent=s};function escapeHTML(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))};
function load(){try{const saved=JSON.parse(localStorage.getItem(STATE_KEY)||'null');if(saved && saved.version===1 && typeof saved.days==='object')data=saved}catch(e){}};
function persist(){try{localStorage.setItem(STATE_KEY,JSON.stringify(data));return true}catch(e){return false}};
function todayData(){return data.days[day]||(data.days[day]={scores:[3,3,3,3],notes:'',point:'',reason:'',close:'',wordNote:'',boundaryNote:'',completed:false,updated:''})}
function changeTab(tab){if(activeTab==='influence'&&tab!=='influence'&&typeof ilSaveCurrent==='function'){ilSaveCurrent();ilStopTimer();ilResetAudio()}activeTab=tab;for(const name of ['today','program','progress','toolkit','influence'])el(name+'Tab').classList.toggle('hidden',tab!==name);document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('selected',b.dataset.tab===tab));if(tab==='progress')renderProgress();if(tab==='program')renderProgram();if(tab==='toolkit')renderToolkit();if(tab==='influence')renderInfluence();}
function setLang(next){lang=next;document.documentElement.lang=lang;document.body.classList.toggle('ar',lang==='ar');document.documentElement.dir=lang==='ar'?'rtl':'ltr';el('enBtn').classList.toggle('active',lang==='en');el('arBtn').classList.toggle('active',lang==='ar');renderAll();}
function setDay(next){if(next<1||next>28)return;stashInputs();day=next;step=0;stopClock();setClock(300);changeTab('today');renderAll();window.scrollTo({top:0,behavior:'smooth'})}
function stashInputs(){if(activeTab!=='today')return;const d=todayData();for(const key of ['point','reason','close','wordNote','boundaryNote']){const e=el('field_'+key);if(e)d[key]=e.value;}d.notes=el('dailyNotes').value;d.scores=[0,1,2,3].map(i=>Number(el('score'+i)?.value||d.scores[i]));}
function renderAll(){for(const [id,key] of Object.entries({navToday:'today',navProgram:'program',navProgress:'progress',navToolkit:'toolkit',headerDesc:'header',prevDay:'prev',nextDay:'next',progressTitle:'total',streakLabel:'streak',avgLabel:'average',saveInfo:'saveInfo',workoutTitle:'workout',timePill:'four',timerTitle:'timer',timerHelp:'timerHelp',timerReset:'reset',recordTitle:'record',recordHelp:'recordHelp',recordStart:'rstart',recordStop:'rstop',dayFocusLabel:'rule',reflectionTitle:'reflection',reflectionHelp:'reflectionHelp',notesLabel:'notes',saveSession:'save',programTitle:'programTitle',programHelp:'programHelp',myProgressTitle:'progressTitle',progressExplain:'progressExplain',weeklyHeadline:'weekly',ratingsHeadline:'ratings',recentHeadline:'recent',backupTitle:'backup',backupExplainer:'backupExplain',exportData:'export',importLabel:'import',clearData:'clear',phraseTitle:'phrases',phraseDesc:'phraseDesc',threeSentenceTitle:'formulaTitle',threeSentenceDesc:'formulaDesc',formulaSample:'formula',healthNote:'health',footer:'footer'}))setText(id,t(key));
 el('dailyNotes').placeholder=t('notesPlaceholder');setText('timerStart',running?t('pause'):t('start'));setText('audioDownload',t('recordDownload'));
 const lesson=LESSONS[day-1],w=WEEKS[lesson.week-1],d=todayData();setText('todayTag',t('week')+' '+lesson.week+' · '+t('day')+' '+day);setText('todayTitle',textFor(lesson,'title'));setText('todayGoal',lang==='en'?w[2]:w[3]);setText('todayChallenge',textFor(lesson,'target'));setText('todayTiming',t('minutes'));setText('dayFocus',textFor(lesson,'target'));el('prevDay').disabled=day===1;el('nextDay').disabled=day===28;
 setText('scoreSaved',d.updated?t('saved'):t('notSaved'));setText('completeSession',d.completed?t('undo'):t('complete'));setText('outOfDays','/ 28 '+t('days'));setText('recordStart',t('rstart'));setText('recordStop',t('rstop'));
 let completed=Object.values(data.days).filter(x=>x.completed).length;setText('doneCount',String(completed));el('overallProgress').style.width=(completed/28*100)+'%';let ratings=Object.values(data.days).filter(x=>x.updated);const avg=ratings.length?(ratings.reduce((s,x)=>s+x.scores.reduce((a,b)=>a+b,0)/4,0)/ratings.length).toFixed(1):'—';setText('avgScore',avg);
 let longest=0,run=0;for(let j=1;j<=28;j++){if(data.days[j]?.completed){run++;longest=Math.max(longest,run)}else run=0}setText('streak',String(longest));
 renderSteps();renderScores();if(activeTab==='program')renderProgram();if(activeTab==='progress')renderProgress();if(activeTab==='toolkit')renderToolkit();if(activeTab==='influence')renderInfluence();
}
function renderSteps(){
 const blocks=el('blockTabs');blocks.innerHTML=t('sections').map((name,i)=>`<button type="button" class="blockBtn ${step===i?'active':''}" data-step="${i}"><span class="n">0${i+1} / 04</span><span class="t">${escapeHTML(name)}</span><span class="tm">${escapeHTML(t('timing'))}</span></button>`).join('');
 blocks.querySelectorAll('[data-step]').forEach(b=>b.addEventListener('click',()=>selectStep(Number(b.dataset.step))));
 const lesson=LESSONS[day-1],d=todayData(),names=t('sections'),goal=[t('wordGoal'),t('thoughtGoal'),t('impactGoal'),t('boundaryGoal')][step],task=[t('wordTask'),t('thoughtTask'),t('impactTask'),t('boundaryTask')][step];
 const ex=WORKED_EXAMPLES[day-1][lang],AR=lang==='ar';
 const labels=AR?{how:'كيف تتدرب؟',steps:'اقرأ المثال بصوت مرتفع، ثم جرّب بكلماتك، وتوقف قليلاً، ثم قيّم نفسك.',example:'مثال واضح — ما يمكنك قوله',bad:'بدلاً من شرح طويل',good:'قل جملة واضحة',use:'استخدم المثال في الخانات',exampleDetail:'أضف مثالاً واحداً فقط عند الحاجة',short:'النسخة المختصرة (حوالي ٣٠ ثانية)',long:'النسخة الأطول (حتى ٦٠ ثانية)',try:'دورك الآن: جرّب بصوتك',repeat:'كرر الرد بهدوء ثلاث مرات وبصوت عادي.',pause:'توقف ثانيتين قبل أن تتكلم.',action:'الخطوة التالية'}:{how:'HOW TO PRACTISE',steps:'Read the example aloud. Try your own words. Pause briefly. Score yourself.',example:'WORKED EXAMPLE — WHAT TO SAY',bad:'Instead of too much background',good:'Lead with a clear point',use:'Use this example in the boxes',exampleDetail:'Add just one concrete example if needed',short:'Short version (about 30 seconds)',long:'Longer version (up to 60 seconds)',try:'YOUR TURN: SAY IT OUT LOUD',repeat:'Repeat the response three times at your normal volume.',pause:'Pause two seconds before speaking.',action:'Next step'};
 let inner=`<div class="mini">${step+1} / 4 · ${escapeHTML(t('timing'))}</div><div class="title">${escapeHTML(names[step])}</div><p class="muted">${escapeHTML(goal)}</p><div class="startGuide"><strong>${labels.how}</strong><p>${labels.steps}</p></div><div class="instruction">${escapeHTML(task)}</div>`;
 const full=`${ex.point} ${ex.reason} ${ex.extra} ${ex.close}`;
 if(step===0){inner+=`<div class="mini">${escapeHTML(t('wordPrompt'))}</div><div class="prompt">${escapeHTML(textFor(lesson,'word'))}</div><div class="modelAnswer"><div class="exampleTitle">${labels.example}</div><p class="line say">${escapeHTML(ex.word)}</p><p class="note">${AR?'إذا نسيت الكلمة، اشرح معناها ووظيفتها بكلمات أبسط، ولا تستعجل.':'If the word disappears, explain its meaning and function using simpler words. Do not rush.'}</p></div><div class="field"><label for="field_wordNote">${escapeHTML(t('wordNote'))}</label><textarea id="field_wordNote" placeholder="${AR?'اكتب شرحك الخاص هنا...':'Write your own explanation here...'}">${escapeHTML(d.wordNote)}</textarea></div>`;}
 if(step===1){inner+=`<div class="mini">${escapeHTML(t('speakingPrompt'))}</div><div class="prompt">${escapeHTML(textFor(lesson,'speech'))}</div><div class="modelAnswer"><div class="exampleTitle">${labels.example}</div><div class="line"><b>1. ${escapeHTML(t('mainPoint'))}:</b> ${escapeHTML(ex.point)}</div><div class="line"><b>2. ${escapeHTML(t('reason'))}:</b> ${escapeHTML(ex.reason)}</div><div class="line"><b>3. ${escapeHTML(t('close'))}:</b> ${escapeHTML(ex.close)}</div><button class="sampleButton" type="button" id="fillExample">${labels.use}</button></div>` + [['point','mainPoint'],['reason','reason'],['close','close']].map(([key,label])=>`<div class="field"><label for="field_${key}">${escapeHTML(t(label))}</label><textarea class="short" id="field_${key}" placeholder="${AR?'اكتب جملة قصيرة هنا...':'Write one short sentence here...'}">${escapeHTML(d[key])}</textarea><div class="char" id="count_${key}"></div></div>`).join('')+`<div class="note" id="lengthHint">${escapeHTML(t('messageHint'))}</div>`;}
 if(step===2){inner+=`<div class="mini">${escapeHTML(t('speakingPrompt'))}</div><div class="prompt">${escapeHTML(textFor(lesson,'speech'))}</div><div class="modelAnswer"><div class="exampleTitle">${labels.short}</div><p class="say">${escapeHTML(ex.point+' '+ex.reason+' '+ex.close)}</p></div><div class="modelAnswer"><div class="exampleTitle">${labels.long}</div><p class="say">${escapeHTML(full)}</p><div class="note">${labels.exampleDetail}: ${escapeHTML(ex.extra)}</div></div><div class="howTo"><b>${labels.try}</b><p>${AR?'اضغط على ٦٠ ثانية أو ٣٠ ثانية في المؤقت، ثم قل الفكرة بهدوء دون إضافة خلفية غير ضرورية.':'Select 60 or 30 seconds in the timer. Speak calmly; do not fill the entire time with unnecessary background.'}</p></div>`;}
 if(step===3){inner+=`<div class="mini">${escapeHTML(t('situation'))}</div><div class="prompt">${escapeHTML(textFor(lesson,'situation'))}</div><div class="modelAnswer"><div class="exampleTitle">${labels.example}</div><div class="say">${escapeHTML(textFor(lesson,'phrase'))}</div><p class="note">${AR?'هذا يحمي دورك في الكلام دون افتراض نية سيئة ودون رفع صوتك.':'This holds your speaking turn without assuming bad intentions or raising your voice.'}</p></div><div class="howTo"><b>${labels.try}</b><p>${labels.pause} ${labels.repeat}</p></div><div class="field"><label for="field_boundaryNote">${escapeHTML(t('boundaryNote'))}</label><textarea id="field_boundaryNote">${escapeHTML(d.boundaryNote)}</textarea></div>`;}
 inner+=`<div class="row" style="margin-top:14px"><button class="secondary" type="button" id="advanceStep">${escapeHTML(t('advance'))}</button></div>`;
 el('exerciseContent').innerHTML=inner;
 el('advanceStep').onclick=()=>selectStep((step+1)%4);
 const sample=el('fillExample');if(sample)sample.onclick=()=>{for(const k of ['point','reason','close'])el('field_'+k).value=ex[k];updateCounts();stashInputs();setText('saveMessage',AR?'تمت إضافة المثال. عدّله ليصبح بكلماتك أنت.':'Example added. Edit it into your own words.');};
 for(const k of ['point','reason','close']){const f=el('field_'+k);if(f)f.addEventListener('input',()=>updateCounts());}
 updateCounts();}
function updateCounts(){for(const k of ['point','reason','close']){const e=el('field_'+k);if(e){let words=e.value.trim().split(/\s+/).filter(Boolean).length;setText('count_'+k,words+' '+(lang==='en'?'words':'كلمات')+(words>30?' · '+(lang==='en'?'consider cutting details':'فكر في الاختصار'):''));}}}
function selectStep(next){stashInputs();step=next;stopClock();setClock(300);renderSteps();}
function renderScores(){const d=todayData();el('scales').innerHTML=t('scales').map((name,i)=>`<div class="scale"><label for="score${i}">${escapeHTML(name)} · <span class="num" id="scoreValue${i}">${d.scores[i]}</span>${escapeHTML(t('ratingUnit'))}</label><input id="score${i}" type="range" min="1" max="5" step="1" value="${d.scores[i]}"></div>`).join('');for(let i=0;i<4;i++)el('score'+i).addEventListener('input',e=>setText('scoreValue'+i,e.target.value));el('dailyNotes').value=d.notes;}
function saveSession(complete=false){stashInputs();let d=todayData();if(complete)d.completed=!d.completed;d.updated=new Date().toISOString();const ok=persist();renderAll();setText('saveMessage',complete?(d.completed?t('doneMsg'):t('already')):t('savedMsg'));if(!ok)setText('saveMessage',lang==='en'?'Browser storage is unavailable. Export a backup now.':'التخزين غير متاح. صدّر نسخة احتياطية الآن.');}
function setClock(s){sec=s;timeLeft=s;renderClock()};function renderClock(){setText('clock',String(Math.floor(timeLeft/60)).padStart(2,'0')+':'+String(timeLeft%60).padStart(2,'0'));setText('timerMode',sec===300?t('timerMode'):(sec===60?'60 sec':'30 sec'));}function stopClock(){running=false;if(timeHandle){clearInterval(timeHandle);timeHandle=null}setText('timerStart',t('start'))}function toggleClock(){if(running){stopClock();return}running=true;setText('timerStart',t('pause'));let last=Date.now();timeHandle=setInterval(()=>{let now=Date.now();let tick=Math.floor((now-last)/1000);if(tick<1)return;last+=tick*1000;timeLeft=Math.max(0,timeLeft-tick);renderClock();if(timeLeft===0){stopClock();try{navigator.vibrate?.([120,60,120])}catch(e){} }},225)}
async function startRecording(){if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){setText('audioStatus',t('recordUnsupported'));return}try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});recordChunks=[];recorder=new MediaRecorder(stream);recorder.ondataavailable=e=>{if(e.data.size)recordChunks.push(e.data)};recorder.onstop=()=>{stream.getTracks().forEach(tr=>tr.stop());if(currentAudio)URL.revokeObjectURL(currentAudio);let blob=new Blob(recordChunks,{type:recorder.mimeType||'audio/webm'});currentAudio=URL.createObjectURL(blob);el('audioPlayer').src=currentAudio;el('audioDownload').href=currentAudio;el('audioDownload').download='ClearSpeak-Day-'+day+'.'+(blob.type.includes('mp4')?'m4a':'webm');el('audioArea').classList.remove('hidden');setText('audioStatus',t('recordReady'));el('recordStart').disabled=false;el('recordStop').disabled=true};recorder.start();el('recordStart').disabled=true;el('recordStop').disabled=false;setText('audioStatus',t('recording'))}catch(e){setText('audioStatus',t('audioErr'));}}
function endRecording(){if(recorder?.state==='recording')recorder.stop()}
function renderProgram(){el('dayList').innerHTML=WEEKS.map((w,wi)=>{const ds=LESSONS.slice(wi*7,wi*7+7),done=ds.filter(l=>data.days[l.day]?.completed).length;return `<div class="wGroup"><div class="wHeader"><div><h3>${escapeHTML(lang==='en'?w[0]:w[1])}</h3><div class="muted small">${escapeHTML(lang==='en'?w[2]:w[3])}</div></div><span class="pillStat">${done}/7</span></div><div class="dayGrid">${ds.map(l=>`<button class="dayBtn ${day===l.day?'active':''} ${data.days[l.day]?.completed?'done':''}" data-day="${l.day}"><span class="dayN">${l.day}</span><span class="dayI">${data.days[l.day]?.completed?'✓':escapeHTML(t('day'))}</span></button>`).join('')}</div></div>`}).join('');el('dayList').querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>setDay(Number(b.dataset.day)))}
function renderProgress(){let saved=Object.values(data.days).filter(d=>d.updated),done=Object.values(data.days).filter(d=>d.completed).length;el('detailStats').innerHTML=`<div class="stat"><div class="value">${done}/28</div><div class="label">${escapeHTML(t('dCount'))}</div></div><div class="stat"><div class="value">${saved.length}</div><div class="label">${escapeHTML(t('rCount'))}</div></div><div class="stat"><div class="value">${escapeHTML(t('metricTip'))}</div><div class="label">${escapeHTML(t('best'))}</div></div>`;
 el('weekBars').innerHTML=WEEKS.map((w,i)=>{let d=LESSONS.slice(i*7,i*7+7).filter(x=>data.days[x.day]?.completed).length;return `<div class="chartrow"><strong>${escapeHTML(t('week'))} ${i+1}</strong><div class="chartbar"><span style="width:${d/7*100}%"></span></div><span class="small">${d}/7</span></div>`}).join('');
 el('metricBars').innerHTML=t('scales').map((name,i)=>{let m=saved.length?saved.reduce((s,d)=>s+Number(d.scores[i]),0)/saved.length:0;return `<div class="chartrow"><strong>${escapeHTML(name)}</strong><div class="chartbar"><span style="width:${m/5*100}%"></span></div><span class="small">${m?m.toFixed(1):'—'}</span></div>`}).join('')+`<p class="note">${escapeHTML(t('csvNote'))}</p>`;
 const recent=Object.keys(data.days).map(Number).filter(n=>data.days[n].updated).sort((a,b)=>b-a).slice(0,10);el('sessionsTable').innerHTML=recent.length?`<table class="tableLike"><thead><tr><th>${escapeHTML(t('day'))}</th><th>${escapeHTML(t('average'))}</th><th>${escapeHTML(t('done'))}</th></tr></thead><tbody>${recent.map(n=>{let d=data.days[n];return `<tr><td>${n}</td><td>${(d.scores.reduce((a,b)=>a+b,0)/4).toFixed(1)}</td><td>${d.completed?'✓':'—'}</td></tr>`}).join('')}</tbody></table>`:`<p class="muted">${escapeHTML(t('noSessions'))}</p>`;}
function renderToolkit(){el('phraseList').innerHTML=PHRASES.map(p=>`<div class="phrase"><strong>${escapeHTML(lang==='en'?p[0]:p[1])}</strong><div class="say">${escapeHTML(lang==='en'?p[2]:p[3])}</div><button type="button" class="secondary copy" data-copy="${escapeHTML(lang==='en'?p[2]:p[3])}">${escapeHTML(t('copy'))}</button></div>`).join('');el('phraseList').querySelectorAll('[data-copy]').forEach(b=>b.onclick=async()=>{try{await navigator.clipboard.writeText(b.dataset.copy);setText('dataMessage',t('copied'));b.textContent=t('copied')}catch(e){b.textContent=b.dataset.copy}})}
function exportProgress(){stashInputs();persist();const content=JSON.stringify({tool:'ClearSpeak',format:1,exportedAt:new Date().toISOString(),data},null,2),blob=new Blob([content],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='ClearSpeak-progress-'+new Date().toISOString().slice(0,10)+'.json';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function importProgress(f){try{const result=JSON.parse(await f.text());if(result.tool!=='ClearSpeak'||result.format!==1||typeof result.data.days!=='object')throw Error('invalid');data={version:1,days:result.data.days};persist();setText('dataMessage',t('importMsg'));renderAll();}catch(e){setText('dataMessage',t('importError'))}}
load();
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{stashInputs();persist();changeTab(b.dataset.tab)});el('enBtn').onclick=()=>{stashInputs();setLang('en')};el('arBtn').onclick=()=>{stashInputs();setLang('ar')};el('prevDay').onclick=()=>setDay(day-1);el('nextDay').onclick=()=>setDay(day+1);el('saveSession').onclick=()=>saveSession(false);el('completeSession').onclick=()=>saveSession(true);el('timerStart').onclick=toggleClock;el('timerReset').onclick=()=>{stopClock();timeLeft=sec;renderClock()};document.querySelectorAll('[data-min]').forEach(b=>b.onclick=()=>{stopClock();setClock(Number(b.dataset.min))});el('recordStart').onclick=startRecording;el('recordStop').onclick=endRecording;el('exportData').onclick=exportProgress;el('importData').onchange=e=>{if(e.target.files?.[0])importProgress(e.target.files[0]);e.target.value=''};el('clearData').onclick=()=>{if(confirm(t('clearConfirm'))){data={version:1,days:{}};persist();renderAll();setText('dataMessage',t('clearMsg'))}};window.addEventListener('pagehide',()=>{stashInputs();persist()});renderAll();
